def add(dom,title,sev,comp,ev,st,conf,impact,rem,desc=None,rep=None):
    desc=desc or (title+'. Evidence summary: '+ev[:300])
    F.append({'id':'RIA-%03d'%(len(F)+1),'domain':dom,'title':title,'severity':sev,'component':comp,'evidence':ev,'status':st,'confidence':conf,'impact':impact,'remediation':rem,'description':desc,
      'reproduction':rep or 'Static only (no execution, no network, no device): open the APK DEX with a DEX parser or JADX and inspect the cited class#method; see installation_assistant_app.md for the traced call chain.'})
